package cn.shangjingu.platform.database;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.Map;
import java.util.UUID;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.testcontainers.containers.PostgreSQLContainer;

class Phase11P015DatabaseIT {
    private static final UUID TENANT=id("00000000-0000-0000-0000-000000001015"),OTHER=id("00000000-0000-0000-0000-000000009015"),CENTER=id("11000000-0000-0000-0000-000000001015"),OTHER_CENTER=id("11000000-0000-0000-0000-000000009015"),EMPLOYEE=id("10000000-0000-0000-0000-000000001015"),ACTOR=id("10000000-0000-0000-0000-000000001016"),OTHER_ACTOR=id("10000000-0000-0000-0000-000000009015"),RULE=id("20000000-0000-0000-0000-000000001015"),DRAFT_RULE=id("20000000-0000-0000-0000-000000001016"),INSTANCE=id("30000000-0000-0000-0000-000000001015"),TRANSACTION=id("40000000-0000-0000-0000-000000001015"),POSTING=id("50000000-0000-0000-0000-000000001015");
    private static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:16.14-alpine3.24").withDatabaseName("postgres").withUsername("postgres").withPassword("phase11-p015-bootstrap");private static String omsUrl;
    @BeforeAll static void migrate()throws Exception{POSTGRES.start();Path root=root();Flyway.configure().dataSource(POSTGRES.getJdbcUrl(),POSTGRES.getUsername(),POSTGRES.getPassword()).locations("filesystem:"+root.resolve("technical-platform/database/flyway/cluster")).cleanDisabled(true).load().migrate();try(Connection c=DriverManager.getConnection(POSTGRES.getJdbcUrl(),POSTGRES.getUsername(),POSTGRES.getPassword());Statement s=c.createStatement()){s.execute("create database sjg_oms");}omsUrl="jdbc:postgresql://"+POSTGRES.getHost()+":"+POSTGRES.getMappedPort(5432)+"/sjg_oms";Flyway f=Flyway.configure().dataSource(omsUrl,POSTGRES.getUsername(),POSTGRES.getPassword()).locations("filesystem:"+root.resolve("technical-platform/database/flyway/oms"),"filesystem:"+root.resolve("technical-platform/database/flyway-overlays/oms")).placeholders(Map.of("sjg_tenant_id",TENANT.toString(),"sjg_tenant_code","PHASE11_P015","sjg_tenant_name","P015 database test")).cleanDisabled(true).load();assertTrue(f.migrate().success);f.validate();assertEquals(0,f.migrate().migrationsExecuted);seed();}
    @AfterAll static void stop(){POSTGRES.stop();}
    @Test void migrationPublishesExactWorkflowPermissionsAndAppendOnlyGrants()throws Exception{try(Connection c=connection();Statement s=c.createStatement()){assertEquals(1,scalar(s,"select count(*) from flyway_schema_history where version='124' and success"));assertEquals(11,scalar(s,workflowCount("wf_node")));assertEquals(11,scalar(s,workflowCount("wf_transition")));assertEquals(5,scalar(s,"select count(*) from iam.permission where tenant_id='"+TENANT+"' and permission_code like 'p015.points.%' and not is_deleted"));assertEquals(1,scalar(s,"select count(*) from workflow.wf_form_definition where tenant_id='"+TENANT+"' and form_code='CTR-P015-F01' and validation_schema->'guards' ? 'append-only' and not is_deleted"));assertEquals(4,scalar(s,"select count(distinct table_name) from information_schema.role_table_grants where grantee='sjg_api_runtime' and table_schema='reward' and table_name in ('point_transaction','point_transaction_event','point_posting_fact','point_balance_fact') and privilege_type='INSERT'"));assertEquals(0,scalar(s,"select count(*) from information_schema.role_table_grants where grantee in ('sjg_api_runtime','sjg_worker_runtime') and table_schema='reward' and table_name in ('point_transaction','point_transaction_event','point_posting_fact','point_balance_fact') and privilege_type in ('UPDATE','DELETE','TRUNCATE')"));}}
    @Test void sourceLedgerPostingAndBalanceFactsAreAppendOnly(){assertSqlState("23505",transactionSql(id("40000000-0000-0000-0000-000000001099"),"P015-DB-DUP","SOURCE-P015-001",100,"AWARD","null"));assertSqlState("55000","update reward.point_transaction set points_delta=999 where id='"+TRANSACTION+"'");assertSqlState("55000","delete from reward.point_posting_fact where id='"+POSTING+"'");assertSqlState("55000","delete from reward.point_transaction_event where point_transaction_id='"+TRANSACTION+"'");}
    @Test void tenantRuleOriginalAndRankRangesFailClosed(){assertSqlState("23514","insert into reward.point_transaction_event(tenant_id,point_transaction_id,event_seq,event_type,evidence,actor_employee_id) values ('"+TENANT+"','"+TRANSACTION+"',2,'CROSS_TENANT','{}','"+OTHER_ACTOR+"')");assertSqlState("23514","insert into reward.point_rank_rule(tenant_id,rule_version_id,rank_code,min_balance,max_balance) values ('"+TENANT+"','"+DRAFT_RULE+"','OVERLAP',50,150)");assertSqlState("55000","update reward.point_rank_rule set min_balance=1 where tenant_id='"+TENANT+"' and rule_version_id='"+RULE+"'");assertSqlState("23514",transactionSql(id("40000000-0000-0000-0000-000000001098"),"P015-BAD-REVERSAL","REV-P015-BAD",-99,"REVERSAL","'"+TRANSACTION+"'"));}
    @Test void effectiveBalanceIsRecomputedFromPostedLedgerFacts()throws Exception{try(Connection c=connection();Statement s=c.createStatement()){assertEquals(100,scalar(s,"select coalesce(sum(p.posted_points),0) from reward.point_posting_fact p join reward.point_transaction x on x.tenant_id=p.tenant_id and x.id=p.point_transaction_id where p.tenant_id='"+TENANT+"' and x.affected_employee_id='"+EMPLOYEE+"'"));assertEquals(100,scalar(s,"select effective_balance from reward.point_balance_fact where point_transaction_id='"+TRANSACTION+"'"));assertEquals(1,scalar(s,"select count(*) from reward.point_rule_version where id='"+RULE+"' and status='PUBLISHED'"));}}
    private static void seed()throws Exception{try(Connection c=connection();Statement s=c.createStatement()){s.execute("insert into core.tenant(id,tenant_code,tenant_name,status) values ('"+OTHER+"','P015_OTHER','P015 Other','ACTIVE')");s.execute("insert into org.organization(id,tenant_id,org_code,org_name,org_type,path,status) values ('"+CENTER+"','"+TENANT+"','P015_CENTER','P015 Center','CENTER','p015_center'::ltree,'ACTIVE'),('"+OTHER_CENTER+"','"+OTHER+"','P015_OTHER','P015 Other','CENTER','p015_other'::ltree,'ACTIVE')");s.execute("insert into org.employee(id,tenant_id,employee_no,person_name,employment_status,hire_date,primary_org_id) values ('"+EMPLOYEE+"','"+TENANT+"','P015-E01','P015 Employee','ACTIVE',current_date-90,'"+CENTER+"'),('"+ACTOR+"','"+TENANT+"','P015-E02','P015 Actor','ACTIVE',current_date-90,'"+CENTER+"'),('"+OTHER_ACTOR+"','"+OTHER+"','P015-X01','P015 Other','ACTIVE',current_date-90,'"+OTHER_CENTER+"')");s.execute("insert into reward.point_rule_version(id,tenant_id,rule_code,version_no,point_kind,event_type,unit_points,min_points,max_points,manual_review_threshold,effective_from,status,created_by) values ('"+RULE+"','"+TENANT+"','P015-GROWTH',1,'GROWTH','SERVICE',10,-1000,1000,500,now()-interval '1 day','DRAFT','"+ACTOR+"'),('"+DRAFT_RULE+"','"+TENANT+"','P015-DRAFT',1,'HONOR','HONOR',10,-1000,1000,500,now()-interval '1 day','DRAFT','"+ACTOR+"')");s.execute("insert into reward.point_rank_rule(tenant_id,rule_version_id,rank_code,min_balance,max_balance) values ('"+TENANT+"','"+RULE+"','BASE',-1000,1000),('"+TENANT+"','"+DRAFT_RULE+"','LOW',-100,100)");s.execute("update reward.point_rule_version set status='PUBLISHED',published_by='"+ACTOR+"',published_at=now() where id='"+RULE+"'");s.execute("insert into workflow.wf_instance(id,tenant_id,instance_no,definition_id,version_id,process_code,business_object_type,business_object_id,title,initiator_id,current_node_code,status,priority,context_snapshot) select '"+INSTANCE+"','"+TENANT+"','P015-WF-001',d.id,v.id,'P015','reward.point_transaction','"+TRANSACTION+"','P015 database ledger','"+ACTOR+"','S09','RUNNING','NORMAL','{}' from workflow.wf_definition d join workflow.wf_version v on v.definition_id=d.id and v.tenant_id=d.tenant_id where d.tenant_id='"+TENANT+"' and d.process_code='P015' and v.status='PUBLISHED' limit 1");s.execute(transactionSql(TRANSACTION,"P015-DB-001","SOURCE-P015-001",100,"AWARD","null"));s.execute("insert into reward.point_transaction_event(tenant_id,point_transaction_id,event_seq,event_type,evidence,actor_employee_id) values ('"+TENANT+"','"+TRANSACTION+"',1,'TRANSACTION_CREATED','{}','"+ACTOR+"')");s.execute("insert into reward.point_posting_fact(id,tenant_id,point_transaction_id,posted_points,rule_version_id,posting_mode,risk_grade,evidence,posted_by) values ('"+POSTING+"','"+TENANT+"','"+TRANSACTION+"',100,'"+RULE+"','AUTOMATIC','L1','{}','"+ACTOR+"')");s.execute("insert into reward.point_balance_fact(tenant_id,point_transaction_id,affected_employee_id,effective_balance,rank_code,evidence,calculated_by) values ('"+TENANT+"','"+TRANSACTION+"','"+EMPLOYEE+"',100,'BASE','{}','"+ACTOR+"')");}}
    private static String transactionSql(UUID id,String no,String source,long points,String action,String original){return "insert into reward.point_transaction(id,tenant_id,business_no,workflow_instance_id,status,created_by,updated_by,source_channel,business_date,subject,reason,priority,risk_level,owner_center_id,owner_employee_id,actual_amount,change_action,change_reason,cost_center_id,currency,employee_event_type,fact_occurred_at,fact_summary,impact_level,points_delta,source_fact_key,affected_employee_id,point_kind,rule_version_id,original_transaction_id,business_object_type,business_object_no,business_object_name,quantity,calculated_points,capped_points) values ('"+id+"','"+TENANT+"','"+no+"','"+INSTANCE+"','LEDGER_ENTRY','"+ACTOR+"','"+ACTOR+"','TEST',current_date,'P015 immutable ledger','Source verified points','NORMAL','L1','"+CENTER+"','"+EMPLOYEE+"',0,'"+action+"','Source verified points','11000000000000000000000000001015','POINT','SERVICE',now(),'Verified service fact','L1',"+points+",'"+source+"','"+EMPLOYEE+"','GROWTH','"+RULE+"',"+original+",'SERVICE_CASE','SERVICE-001','Verified service',1,"+points+","+points+")";}
    private static void assertSqlState(String expected,String sql){SQLException e=assertThrows(SQLException.class,()->{try(Connection c=connection();Statement s=c.createStatement()){s.execute(sql);}});assertEquals(expected,e.getSQLState());}private static String workflowCount(String table){return "select count(*) from workflow."+table+" x join workflow.wf_version v on v.id=x.version_id and v.tenant_id=x.tenant_id join workflow.wf_definition d on d.id=v.definition_id and d.tenant_id=v.tenant_id where d.process_code='P015' and v.status='PUBLISHED' and x.tenant_id='"+TENANT+"' and not x.is_deleted";}private static long scalar(Statement s,String sql)throws SQLException{try(var r=s.executeQuery(sql)){r.next();return r.getLong(1);}}private static Connection connection()throws SQLException{return DriverManager.getConnection(omsUrl,POSTGRES.getUsername(),POSTGRES.getPassword());}private static UUID id(String value){return UUID.fromString(value);}private static Path root(){Path p=Path.of("").toAbsolutePath();while(p!=null){if(Files.exists(p.resolve("AGENT.md")))return p;p=p.getParent();}throw new IllegalStateException("repository root not found");}
}
